contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 burnValue) public {
        require(c.owner() == address(this));

        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(burnValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool supplyOk = (c.balanceOf(address(this)) == balanceBefore && c.totalSupply() == totalSupplyBefore) || (balanceBefore >= burnValue && c.balanceOf(address(this)) == balanceBefore - burnValue && c.totalSupply() == totalSupplyBefore - burnValue);

        assert(supplyOk);
    }

    receive() external payable {}
}

